-- Vision d'Abdias. Ainsi– a–dit Adonai YHWH concernant–Édom: message nous–avons–entendu de–la–part–de YHWH et–envoyé parmi–les–nations a–été–envoyé: Levez-vous et–levons-nous contre–elle pour–la–bataille!

